        m=re.match(r'^([A-Z]{1,3}-?\d{3,5}) (.*)$',l)
        if m and 'HS' not in l:
            # description line then hs line
            desc=m.group(2)
            hs=None
            for j in range(i+1,min(i+4,len(lines))):
                h=re.match(r'^(\d{4}\.\d{2}\.\d{4}) ',lines[j])
                if h: hs=h.group(1);break
            if hs: rows[(p,m.group(1))].add((desc.strip(),hs))
print(len(rows))
for k,v in sorted(rows.items()): print(k,v)
